const fs = require('fs-extra');
const path = require('path');

const outputFileName = "LuaTypes.lua"

function gen(config, outputManifestPath) {
    fs.ensureDirSync(outputManifestPath);

    var json = JSON.stringify(config, null, 2)

    var text = `

local text = [[${json}]]

return game.HttpService:JSONDecode(text)

    `


    fs.writeFileSync(path.join(outputManifestPath, outputFileName), text);
    console.log(`write file ${path.join(outputManifestPath, outputFileName)}`)

}


module.exports = gen;